steps.script:
var main = tree.root.get_node("Main")
TerrainManager.set_meta("tac_saved_layout", TerrainManager.current_layout)
TerrainManager.load_terrain_layout("take_and_hold_vs_reconnaissance_1")
var units = GameState.state["units"]
var px = 40.0
for uid in units:
	if uid != "U_FENRISIAN_WOLVES_A" and uid != "U_BOYZ_B":
		for m in units[uid].get("models", []):
			m["alive"] = false
		continue
	units[uid]["flags"] = {}
	units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
var wolves = units["U_FENRISIAN_WOLVES_A"]["models"]
for i in range(wolves.size()):
	wolves[i]["alive"] = (i == 0)
wolves[0]["position"] = {"x": 31.5 * px, "y": 43.0 * px}
wolves[0]["rotation"] = 0.0
var k = 0
for m in units["U_BOYZ_B"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (3.0 + (k % 5) * 1.4) * px, "y": (20.0 + int(k / 5) * 1.4) * px}
		k += 1
PhaseManager.get_current_phase_instance().update_local_state(GameState.create_snapshot())
main._recreate_unit_visuals()
main.movement_controller._refresh_unit_list()
return "ok"

var ph = PhaseManager.get_current_phase_instance()
var a = Vector2(31.5, 43.0) * 40.0
var top = Vector2(27.5, 43.0) * 40.0
var far = Vector2(23.0, 43.0) * 40.0
var uid = "U_FENRISIAN_WOLVES_A"
var kws = GameState.get_unit(uid)["meta"]["keywords"]
var top_id = str(TerrainManager.get_terrain_at_position(top).get("id", ""))
var climb_top = float(ph._get_vertical_climb_cost(a, top, uid))
var pen_top = float(ph._get_movement_terrain_penalty(a, top, uid, false))
var climb_far = float(ph._get_vertical_climb_cost(a, far, uid))
var pen_far = float(ph._get_movement_terrain_penalty(a, far, uid, false))
var chg_far = float(TerrainManager.calculate_charge_terrain_penalty(a, far, false, kws))
print("[%s] onto the generator top: dest=%s climb=%.1f move_penalty=%.1f | across it: climb=%.1f move_penalty=%.1f charge_penalty=%.1f" % ["beasts_dense_feature_cross_free_end_climbs_11e", top_id, climb_top, pen_top, climb_far, pen_far, chg_far])
return "%s|%.1f|%.1f|%.1f|%.1f|%.1f" % [top_id, climb_top, pen_top, climb_far, pen_far, chg_far]

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_FENRISIAN_WOLVES_A", {})
var staged = md.get("staged_moves", [])
if staged.is_empty():
	return "not staged"
var d = staged[0].get("dest")
var booked = float(md.get("model_distances", {}).get("U_FENRISIAN_WOLVES_A:m1", -1.0))
print("[%s] onto the generator top staged at (%.2f, %.2f)in, booked %.2fin" % ["beasts_dense_feature_cross_free_end_climbs_11e", d.x / 40.0, d.y / 40.0, booked])
return "%s|%s" % [str(absf(d.x / 40.0 - 27.5) < 0.3 and absf(d.y / 40.0 - 43.0) < 0.3), str(absf(booked - 7.5) < 0.3)]

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_FENRISIAN_WOLVES_A", {})
var staged = md.get("staged_moves", [])
if staged.is_empty():
	return "not staged"
var d = staged[0].get("dest")
var booked = float(md.get("model_distances", {}).get("U_FENRISIAN_WOLVES_A:m1", -1.0))
print("[%s] across the generator staged at (%.2f, %.2f)in, booked %.2fin" % ["beasts_dense_feature_cross_free_end_climbs_11e", d.x / 40.0, d.y / 40.0, booked])
return "%s|%s" % [str(absf(d.x / 40.0 - 23.0) < 0.3 and absf(d.y / 40.0 - 43.0) < 0.3), str(absf(booked - 8.5) < 0.3)]

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[beasts_dense_feature_cross_free_end_climbs_11e log] ERROR lines = ", n, " ", bad.slice(0, 3))
return n

if TerrainManager.has_meta("tac_saved_layout"):
	var lay = str(TerrainManager.get_meta("tac_saved_layout"))
	TerrainManager.remove_meta("tac_saved_layout")
	if lay != "":
		TerrainManager.load_terrain_layout(lay)
return true
